export function regionPoints(layer){let points=layer.points||[];if(layer.type==='split'){const boundary=[];for(let i=0;i<=40;i++){const y=i/40,x=(layer.position??.5)+Math.tan((layer.angle||0)*Math.PI/180)*(y-.5)+(layer.curve||0)*Math.sin(y*Math.PI*2);boundary.push([x,y])}points=layer.side==='right'?[[1,0],[1,1],...boundary.reverse()]:[[0,0],...boundary,[0,1]]}if(!points.length)return [];const cx=points.reduce((a,p)=>a+p[0],0)/points.length,cy=points.reduce((a,p)=>a+p[1],0)/points.length,a=(layer.rotation||0)*Math.PI/180,s=layer.scale??1;return points.map(([x,y])=>[cx+(x-cx)*Math.cos(a)*s-(y-cy)*Math.sin(a)*s+(layer.offsetX||0),cy+(x-cx)*Math.sin(a)*s+(y-cy)*Math.cos(a)*s+(layer.offsetY||0)])}
